parameters.callback:
${{
  "oneOf": [
    {
      "type": "string",
      "description": "Specifies the name of the global PHP function to be invoked."
    },
    {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 2,
      "maxItems": 2,
      "description": "Specifies an array with two elements. The first element is either the name of an object (as a string, e.g., \"$wpdb\") or a class name. The second element is the method to invoke on that object or class."
    }
  ],
  "description": "Specifies the operation to be executed. It can either be a string representing a global PHP function name or an array with two elements. For object method invocations, the first element must be the object name (e.g., \"$wpdb\" for the WordPress database object), and the second element must be the method name to invoke on that object."
}
}

